import html
from pathlib import Path

def make_form(lang):
    en=lang=='en'
    def t(it,eng): return eng if en else it
    def select(name,label,options,required=True):
        return '<label>'+label+'<select name="'+name+'" '+('required' if required else '')+'><option value="">'+t('Seleziona…','Please select…')+'</option>'+''.join('<option value="'+v+'">'+html.escape(t(it,eng))+'</option>' for v,it,eng in options)+'</select></label>'
    cats=[('solitaire','Anello solitario','Solitaire ring'),('multi-stone','Anello con più pietre','Multi-stone ring'),('earrings','Orecchini','Earrings'),('necklace','Collana / pendente','Necklace / pendant'),('bracelet','Bracciale','Bracelet'),('brooch','Spilla','Brooch'),('loose-diamond','Pietra sciolta','Loose diamond'),('gemstone','Pietra preziosa','Coloured gemstone'),('watch','Orologio','Watch'),('other','Altro','Other')]
    brands=[(v,v,v) for v in ['Rolex','Patek Philippe','Audemars Piguet','Cartier','Vacheron Constantin','Richard Mille','Piaget','Jacob & Co']]
    weights=[('under-1','Meno di 1 ct','Under 1 ct'),('1-2','1–2 ct','1–2 ct'),('2-3','2–3 ct','2–3 ct'),('2-5','2–5 ct','2–5 ct'),('3-5','3–5 ct','3–5 ct'),('over-5','Oltre 5 ct','Over 5 ct'),('unknown','Non lo so','Not sure')]
    return f'''<header class="top"><a href="index.html">◇ ComproDiamanti.it</a><a href="acquistiamo.html">{t('Cosa acquistiamo','What we buy')}</a><a href="chisiamo.html">{t('Chi siamo','About us')}</a><a href="faq.html">FAQ</a></header>
    <main class="quote-main"><p class="kicker">{t('Servizio 100% gratuito e senza impegno','Completely free, with no obligation')}</p><h1>{t('Quotazione gratuita e senza impegno','A free, no-obligation valuation')}</h1><p>{t('Il servizio di acquisto diretto di La Diamanteria. Senza aste né intermediari. Milano, dal 2009.','La Diamanteria’s direct buying service. No auctions or intermediaries. Established in Milan in 2009.')}</p>
    <div class="trust-line"><span>{t('Compratore diretto','Direct buyer')}</span><span>{t('Bonifico tracciabile','Bank transfer')}</span><span>GIA / HRD / IGI</span></div>
    <p class="hint">{t('Valutiamo diamanti naturali da 1 carato per pietra, gemme di colore anche più piccole e orologi dei marchi indicati.','We assess natural diamonds of one carat or more per stone, smaller coloured gemstones and watches from the brands listed below.')}</p>
    <div class="progress" aria-hidden="true">{''.join('<span></span>' for _ in range(6))}</div><p id="step-label" aria-live="polite"></p>
    <form id="valuation-form" class="panel" novalidate enctype="multipart/form-data">
    <input type="hidden" name="language" value="{lang}"><div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
    <fieldset data-step="1"><legend>{t('Quale oggetto vuoi vendere?','What would you like to sell?')}</legend>{select('cat',t('Tipo di oggetto','Item type'),cats)}</fieldset>
    <fieldset data-step="2"><legend>{t('Hai altri oggetti?','Do you have other items?')}</legend>{select('multi',t('Più oggetti da valutare','Other items to be valued'),[('yes','Sì','Yes'),('no','No','No')])}<label id="others-field">{t('Descrivi gli altri oggetti','Describe your other items')}<textarea name="others" maxlength="1500"></textarea></label></fieldset>
    <fieldset data-step="3"><legend>{t('Dettagli dell’oggetto','Item details')}</legend>
    <div data-kind="watch">{select('brand',t('Marca dell’orologio','Watch brand'),brands)}</div>
    <div data-kind="gemstone">{select('stone',t('Tipo di pietra','Gemstone type'),[('ruby','Rubino','Ruby'),('sapphire','Zaffiro','Sapphire'),('emerald','Smeraldo','Emerald'),('other','Altra pietra','Other gemstone')])}</div>
    <div data-kind="stone">{select('ct',t('Peso della pietra principale','Carat weight of the main stone'),weights)}</div>
    <div data-kind="diamond">{select('origin',t('Origine del diamante','Diamond origin'),[('natural','Naturale','Natural'),('unknown','Non lo so','Not sure')])}<p class="hint">{t('Non acquistiamo diamanti creati in laboratorio.','We do not buy laboratory-grown diamonds.')}</p></div></fieldset>
    <fieldset data-step="4"><legend>{t('Certificati e documenti','Grading reports and documents')}</legend>
    <div data-kind="stone">{select('cert',t('Certificato disponibile','Grading report available'),[('GIA','GIA','GIA'),('HRD','HRD','HRD'),('IGI','IGI','IGI'),('none','Nessun certificato','No report')])}<p class="hint">{t('Non acquistiamo diamanti con certificati AIG, GRA, GWLAB o ALGT.','We do not buy diamonds accompanied by AIG, GRA, GWLAB or ALGT reports.')}</p></div>
    <div data-kind="watch">{select('kit',t('Corredo disponibile','Box and papers available'),[('full-set','Scatola e garanzia','Box and papers'),('papers','Solo garanzia','Papers only'),('none','Nessun documento','No papers')])}</div></fieldset>
    <fieldset data-step="5"><legend>{t('Foto e certificati','Photographs and grading reports')}</legend><p>{t('Facoltativo: allega foto nitide dell’oggetto e gli eventuali certificati.','Optional: attach clear photographs of your item and any grading reports.')}</p><label>{t('Seleziona i file','Choose files')}<input type="file" name="photos[]" id="photos" accept="image/jpeg,image/png,image/webp,application/pdf" multiple></label><p class="hint">{t('JPG, PNG, WebP o PDF. Massimo 6 file, 5 MB ciascuno e 20 MB complessivi.','JPG, PNG, WebP or PDF. Up to 6 files, 5 MB each and 20 MB in total.')}</p><ul id="selected-files"></ul></fieldset>
    <fieldset data-step="6"><legend>{t('Come possiamo contattarti?','How can we contact you?')}</legend><div class="form-grid"><label>{t('Nome e cognome','Full name')}<input name="name" autocomplete="name" required minlength="2" maxlength="120"></label>{select('pref',t('Contatto preferito','Preferred contact method'),[('WhatsApp','WhatsApp','WhatsApp'),('phone','Telefono','Telephone'),('email','Email','Email')])}<label>{t('Telefono','Telephone')}<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label>Email<input name="email" type="email" autocomplete="email" maxlength="254"></label></div>
    <details><summary>{t('Come utilizziamo i tuoi dati','How we use your data')}</summary><p>{t('La Diamanteria utilizza i contatti e gli allegati che invii per esaminare l’oggetto e rispondere alla richiesta di valutazione. Gli allegati sono accessibili solo agli amministratori autorizzati. Non caricare documenti d’identità: saranno richiesti solo se concludiamo la vendita. Per informazioni sul trattamento dei dati contatta sl@ladiamanteria.com.','La Diamanteria uses the contact details and attachments you submit to assess your item and respond to your valuation enquiry. Attachments can only be accessed by authorised administrators. Please do not upload identity documents: these are required only if you decide to sell to us. For information about how your data is used, contact sl@ladiamanteria.com.')}</p></details>
    <label><input name="consent" type="checkbox" value="1" required>{t('Ho letto le informazioni sul trattamento dei dati per questa richiesta.','I have read the information about how my data will be used for this enquiry.')}</label><h2>{t('Riepilogo','Your enquiry at a glance')}</h2><dl id="recap"></dl></fieldset>
    <p id="form-error" class="error" role="alert" aria-live="assertive"></p><div class="actions"><button type="button" id="back">{t('Indietro','Back')}</button><button type="submit" id="next">{t('Continua','Continue')}</button></div></form>
    <noscript><p>{t('Attiva JavaScript per utilizzare il modulo oppure contattaci via email:','Please enable JavaScript to use the form, or contact us by email:')} <a href="mailto:sl@ladiamanteria.com">sl@ladiamanteria.com</a>.</p></noscript></main><footer>La Diamanteria · Via Vincenzo Monti 47, Milano · <a href="tel:+3902466891">+39 02 466891</a></footer>'''

def make_thanks(lang):
    def t(it,en):return en if lang=='en' else it
    return f'''<header class="top"><a href="index.html">◇ ComproDiamanti.it</a></header><main class="quote-main panel"><p>{t('Valutazione gratuita','Free valuation')}</p><h1>{t('Grazie per la tua richiesta','Thank you for your enquiry')}</h1><p id="receipt" class="receipt" role="status"></p><p>{t('Un nostro gemmologo esaminerà le informazioni e gli allegati inviati e ti contatterà con il metodo che hai scelto. La valutazione definitiva richiede l’esame dell’oggetto.','One of our gemmologists will review the information and attachments you have submitted and contact you using your preferred method. A final valuation requires an examination of the item.')}</p><h2>{t('I prossimi passaggi','What happens next')}</h2><ol><li>{t('Esame della richiesta da parte del gemmologo.','A gemmologist reviews your enquiry.')}</li><li>{t('Se necessario, appuntamento nella nostra sede di Milano.','An appointment at our Milan showroom, if needed.')}</li><li>{t('Offerta diretta e pagamento con bonifico se decidi di vendere.','An offer directly from us, with payment by bank transfer if you decide to sell.')}</li></ol><a class="button" href="index.html">{t('Torna al sito','Back to the website')}</a></main>'''

for lang in ['it','en']:
    Path('tools/valutazione.'+lang+'.html').write_text(make_form(lang),encoding='utf-8')
    Path('tools/grazie.'+lang+'.html').write_text(make_thanks(lang),encoding='utf-8')
